//! 🔺️ delete-animation leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfAnimation;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::delete_animation::mutation::{apply, validate, GltfDeleteAnimationPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{animations_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.delete-animation.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfDeleteAnimationOperation { Insert { position: usize, item: GltfAnimation }, Delete { index: usize, removed: GltfAnimation }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfDeleteAnimationDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfDeleteAnimationPayload, pub operation: GltfDeleteAnimationOperation }
fn operation(payload: &GltfDeleteAnimationPayload, base: &GltfSnapshot) -> GltfDeleteAnimationOperation { GltfDeleteAnimationOperation::Delete { index: payload.index, removed: base.document.animations[payload.index].clone() } }
fn touched_paths(payload: &GltfDeleteAnimationPayload) -> Vec<String> { vec![format!("document/animations/{}", payload.index)] }
pub fn validate_diff(diff: &GltfDeleteAnimationDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfDeleteAnimationDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfDeleteAnimationOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Animations, &Change::Insert(*position))?; next.document.animations.insert(*position, item.clone());  }, GltfDeleteAnimationOperation::Delete { index, .. } => { animations_op(&mut next, GltfTopLevelFamily::Animations, *index, None, None)?;  }, GltfDeleteAnimationOperation::Move { index, position } => { animations_op(&mut next, GltfTopLevelFamily::Animations, *index, Some(*position), None)?;  }, GltfDeleteAnimationOperation::Reorder { order } => { animations_op(&mut next, GltfTopLevelFamily::Animations, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfDeleteAnimationDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfDeleteAnimationPayload, base: &GltfSnapshot) -> Result<GltfDeleteAnimationDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfDeleteAnimationDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfDeleteAnimationPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Animations, base, &next)) }
